cd /tmp/binlog-reader && cat > Program.cs << 'EOF'
using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== ALL ERRORS (including cascading) ===");
build.VisitAllChildren<Error>(error => {
    Console.WriteLine($"[Project: {error.ProjectFile}]");
    Console.WriteLine($"  File: {error.File}");
    Console.WriteLine($"  Line {error.LineNumber}, Col {error.ColumnNumber}");
    Console.WriteLine($"  Code: {error.Code}");
    Console.WriteLine($"  Text: {error.Text}");
    Console.WriteLine();
});

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");

Console.WriteLine("\n=== PROJECT RESULTS ===");
build.VisitAllChildren<Project>(project => {
    // skip metaproj
    if (project.ProjectFile != null && !project.ProjectFile.Contains("metaproj"))
        Console.WriteLine($"  {System.IO.Path.GetFileName(project.ProjectFile)} - Succeeded: {project.Succeeded}");
});
EOF
